artist_first_positions = {}
for recommendation_index, recommendation in enumerate(recommendations):
    song = recommended_songs_by_id[recommendation["song_id"]]
    artist_ids_seen_in_song = set()
    for artist in song["artists"]:
        artist_id = artist["id"]
        if artist_id in artist_ids_seen_in_song:
            continue
        artist_ids_seen_in_song.add(artist_id)
        artist_recommendation_counts[artist_id] = artist_recommendation_counts.get(artist_id, 0) + 1
        artist_names_from_songs[artist_id] = artist["name"]
        if artist_id not in artist_first_positions:
            artist_first_positions[artist_id] = recommendation_index
if not artist_recommendation_counts:
    raise RuntimeError("No artists were present in the recommendations")
maximum_recommendation_count = max(artist_recommendation_counts.values())
